package net.civeira.phylax.feature.observe.source.sync;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.resourceserver.domain.gateway.ResourceServerFilter;
import net.civeira.phylax.feature.access.resourceserver.domain.gateway.ResourceServerQueryRepositoryGateway;
import net.civeira.phylax.feature.observe.source.ObservedOriginReader;
import net.civeira.phylax.feature.observe.source.OriginRef;

/**
 * Every resource server as an origin, for the reconciliation at startup.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ResourceServerObservedOriginReader implements ObservedOriginReader {

  private final ResourceServerQueryRepositoryGateway gateway;

  @Override
  public String originType() {
    return "api";
  }

  @Override
  public List<OriginRef> readAll() {
    return gateway.list(ResourceServerFilter.builder().build()).stream()
        .map(ResourceServerObservedSourceSync::toOrigin).toList();
  }
}
